begin;
reset role;
select prepare_opening_ceremony_layout(f(1),f(33),-1);
select save_ceremony(f(1),f(33),'opening',(select revision from ceremony_plans where kind='opening'),'configure','{"location":"Synthetic hall","capacity":3540,"startsAt":"2026-10-25T16:30","endsAt":"2026-10-25T19:00","state":"validated","attendancePart":"afternoon"}');
select set_ceremony_map(f(1),f(33),(select id from ceremony_plans where kind='opening'),(select revision from ceremony_plans where kind='opening'),f(6990),'publish',jsonb_build_object('versionId',(select id from ceremony_map_versions where state='draft')));
delete from event_attendance_choices where registration_id in(f(10),f(11));
insert into event_attendance_choices(registration_id,day,day_part,choice) values(f(10),'2026-10-25','afternoon','no'),(f(11),null,null,'unknown');
create function public.desk_test(payload jsonb,actor integer default 31) returns jsonb language sql as $$ select assign_ceremony_seats(f(1),f(actor),(select id from ceremony_plans where kind='opening'),(select revision from ceremony_plans where kind='opening'),gen_random_uuid(),payload) $$;
set local role service_role;
do $$ declare p uuid; sector uuid; unnumbered uuid; seats uuid[]; blocked uuid; payload jsonb; version integer; request uuid:=f(6991); before_count integer; v jsonb; begin
 select id,revision into p,version from ceremony_plans where kind='opening';
 select id into sector from ceremony_sectors where layout_code='A1';
 select id into unnumbered from ceremony_sectors where layout_code='F';
 select array_agg((s->>'id')::uuid order by s->>'row',s->>'number') into seats from ceremony_map_versions mv,jsonb_array_elements(mv.seats) s where mv.plan_id=p and mv.state='published' and (s->>'sectorId')::uuid=sector;
 select (s->>'id')::uuid into blocked from ceremony_map_versions mv,jsonb_array_elements(mv.seats) s where mv.plan_id=p and mv.state='published' and (s->>'blocked')::boolean limit 1;
 payload:=jsonb_build_object('action','assign','sectorId',sector,'quantity',2,'seatIds',jsonb_build_array(seats[1],seats[2]),'subjects',jsonb_build_array(jsonb_build_object('registrationId',f(10),'childId',null),jsonb_build_object('registrationId',f(10),'childId',f(40))));
 assert assign_ceremony_seats(f(1),f(31),p,version,request,payload)->>'status'='saved';
 assert assign_ceremony_seats(f(1),f(31),p,version,request,payload)->>'status'='saved','replay must not duplicate';
 assert (select count(*)=2 from ceremony_nominees where plan_id=p and revoked_at is null);
 assert (select bool_and(not app.ceremony_nominee_needs_review(id)) from ceremony_nominees where plan_id=p),'absence is a priority signal, not invalidation';
 assert (select count(*)=2 from ceremony_seat_claims where plan_id=p and nominee_id is not null and released_at is null);
 assert (select choice='no' from event_attendance_choices where registration_id=f(10));
 -- Valid first child followed by another parent's child: all effects must roll back.
 payload:=jsonb_set(payload,'{seatIds}',jsonb_build_array(seats[3],seats[4]));
 payload:=jsonb_set(payload,'{subjects}',jsonb_build_array(jsonb_build_object('registrationId',f(10),'childId',f(41)),jsonb_build_object('registrationId',f(10),'childId',f(42))));
 select revision into version from ceremony_plans where id=p;
 assert desk_test(payload)->>'status'='ineligible';
 assert (select revision=version from ceremony_plans where id=p),'partial revision';
 assert (select count(*)=2 from ceremony_nominees where plan_id=p and revoked_at is null),'partial family';
 payload:=jsonb_build_object('action','assign','sectorId',sector,'quantity',1,'seatIds',jsonb_build_array(seats[3]),'subjects',jsonb_build_array(jsonb_build_object('registrationId',f(11),'childId',null)));
 assert desk_test(payload)->>'status'='saved','unknown attendance excluded';
 assert desk_test(payload)->>'status'='occupied';
 begin perform desk_test(jsonb_set(payload,'{seatIds}',jsonb_build_array(blocked)));raise exception 'protocol selectable';exception when invalid_parameter_value then null;end;
 v:=get_ceremony_seats_desk(f(1),f(31),'opening');
 assert not v ? 'people' and not v ? 'history';
 assert jsonb_array_length(v->'nominees')=3;
 foreach before_count in array array[30,32,34,35,36,37] loop
  begin perform get_ceremony_seats_desk(f(1),f(before_count),'opening');raise exception 'unauthorized read';exception when insufficient_privilege then null;end;
  begin perform desk_test(payload,before_count);raise exception 'unauthorized write';exception when insufficient_privilege then null;end;
 end loop;
 begin perform save_ceremony(f(1),f(31),'opening',(select revision from ceremony_plans where id=p),'quota',jsonb_build_object('id',gen_random_uuid(),'sectorId',sector,'quantity',1,'category','Bypass'));raise exception 'manager changed quota';exception when insufficient_privilege then null;end;
 assert not has_function_privilege('authenticated','public.assign_ceremony_seats(uuid,uuid,uuid,integer,uuid,jsonb)','execute');
end $$;
reset role;
insert into groups(id,event_id,name,is_active) values(f(6900),f(1),'Delegazione sintetica',true);
update participant_group_assignments set is_current=false where registration_id=f(10);
insert into participant_group_assignments(registration_id,group_id,is_current,source,status) values(f(10),f(6900),true,'manager','confirmed');
insert into participants(id,first_name,last_name,public_code) values(f(6950),'F member','Test','FTST');
insert into registrations(id,event_id,participant_id,status) values(f(6951),f(1),f(6950),'submitted');
insert into participant_group_assignments(registration_id,group_id,is_current,source,status) values(f(6951),f(6900),true,'manager','confirmed');
set local role service_role;
do $$ declare s uuid; seats uuid[]; payload jsonb; gid uuid:=f(6900); before_qty integer; begin
 select id into s from ceremony_sectors where layout_code='B1';
 select array_agg((x->>'id')::uuid order by x->>'row',x->>'number') into seats from ceremony_map_versions v,jsonb_array_elements(v.seats) x where v.state='published' and (x->>'sectorId')::uuid=s;
 payload:=jsonb_build_object('action','group','sectorId',s,'quantity',2,'seatIds',jsonb_build_array(seats[1],seats[2]),'groupId',gid);
 assert desk_test(payload)->>'status'='saved';
 assert desk_test(jsonb_set(payload,'{seatIds}',jsonb_build_array(seats[3],seats[4])))->>'status'='saved','extend delegation';
 assert (select quantity=4 from ceremony_allocations where group_id=gid and revoked_at is null);
 payload:=jsonb_build_object('action','assign','sectorId',s,'quantity',1,'seatIds',jsonb_build_array(seats[1]),'subjects',jsonb_build_array(jsonb_build_object('registrationId',f(11),'childId',f(42))));
 assert desk_test(payload)->>'status'='ineligible','foreign member';
 payload:=jsonb_set(payload,'{subjects}',jsonb_build_array(jsonb_build_object('registrationId',f(10),'childId',f(41))));
 assert desk_test(payload)->>'status'='saved','reserved group chair to member child';
 select id into s from ceremony_sectors where layout_code='F';
 assert desk_test(jsonb_build_object('action','group','sectorId',s,'quantity',2,'seatIds','[]'::jsonb,'groupId',gid))->>'status'='saved';
 assert desk_test(jsonb_build_object('action','assign','sectorId',s,'quantity',1,'seatIds','[]'::jsonb,'subjects',jsonb_build_array(jsonb_build_object('registrationId',f(6951),'childId',null))))->>'status'='saved';
 assert (select sum(a.quantity)=2 from ceremony_allocations a join ceremony_quotas q on q.id=a.quota_id where q.sector_id=s and a.revoked_at is null),'F reserve counted twice';
 -- This member is already assigned elsewhere: no duplicate ticket in F.
 payload:=jsonb_set(payload,'{sectorId}',to_jsonb(s));payload:=jsonb_set(payload,'{seatIds}','[]'::jsonb);
 assert desk_test(payload)->>'status'='duplicate';
 assert (select count(*)=7 from ceremony_seat_claims where released_at is null);
end $$;
reset role;
select 'PASS desk: atomic families, all attendance states, delegation seats, replay, protocol, roles and no directory payload';
rollback;
